import { Box, Container } from "@mui/material";
import { Outlet, useLocation } from "react-router-dom";

import DashboardSidebar from "../components/layout/DashboardSidebar";

const pageTitles: Record<string, { title: string; subtitle: string }> = {
  "/forecast": {
    title: "COAL STOCKPILE FORECAST",
    subtitle: "Real-time AI predictions with weather intelligence",
  },
  "/model-performance": {
    title: "MODEL PERFORMANCE",
    subtitle: "Accuracy metrics and validation analytics",
  },
  "/inference": {
    title: "SYSTEM HEALTH",
    subtitle: "Pipeline execution and resource monitoring",
  },
  "/inference-monitoring": {
    title: "ACTIVITY MONITOR",
    subtitle: "Live inference tracking and performance",
  },
};

const DashboardLayout = () => {
  const location = useLocation();
  const page = pageTitles[location.pathname] ?? {
    title: "ESKOM FORECAST",
    subtitle: "Advanced Analytics Platform",
  };

  return (
    <Box
      sx={{
        display: "flex",
        minHeight: "100vh",
        bgcolor: "#0A0A0A",
        position: "relative",
      }}
    >
      {/* Industrial grid pattern */}
      <Box
        sx={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundImage: `
            linear-gradient(rgba(226, 35, 26, 0.05) 1px, transparent 1px),
            linear-gradient(90deg, rgba(226, 35, 26, 0.05) 1px, transparent 1px)
          `,
          backgroundSize: "40px 40px",
          opacity: 0.4,
          pointerEvents: "none",
          zIndex: 0,
        }}
      />

      {/* Sidebar */}
      <DashboardSidebar />

      {/* Main Content Area */}
      <Box
        sx={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          minWidth: 0,
          position: "relative",
          zIndex: 1,
        }}
      >
        {/* Header with Eskom red stripe */}
        <Box
          sx={{
            position: "sticky",
            top: 0,
            zIndex: 1000,
            backgroundColor: "#1A1A1A",
            borderBottom: "4px solid #E2231A",
            boxShadow: "0 4px 20px rgba(0, 0, 0, 0.5)",
          }}
        >
          <Container
            maxWidth={false}
            sx={{
              px: { xs: 2, sm: 3, lg: 4 },
              py: 2.5,
            }}
          >
            <Box>
              <Box
                sx={{
                  fontSize: "1.5rem",
                  fontWeight: 900,
                  color: "#FFFFFF",
                  letterSpacing: "0.05em",
                  mb: 0.5,
                  textTransform: "uppercase",
                  textShadow: "0 2px 4px rgba(0, 0, 0, 0.5)",
                }}
              >
                {page.title}
              </Box>
              <Box
                sx={{
                  fontSize: "0.875rem",
                  color: "rgba(255, 255, 255, 0.6)",
                  fontWeight: 600,
                  letterSpacing: "0.02em",
                }}
              >
                {page.subtitle}
              </Box>
            </Box>
          </Container>
        </Box>

        {/* Page Content */}
        <Box
          component="main"
          sx={{
            flex: 1,
            overflow: "auto",
            py: 4,
          }}
        >
          <Container
            maxWidth={false}
            sx={{
              px: { xs: 2, sm: 3, lg: 4 },
            }}
          >
            <Outlet />
          </Container>
        </Box>
      </Box>
    </Box>
  );
};

export default DashboardLayout;
